local k={60,70,140,253,44,227,105,75,162,235,245,47,146,42,128,164,218,184,93,243,194,180,67,82,195,168,47,38,163,68,246,115}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
